mapper.sql:
FROM sys_user u JOIN sys_user_organization uo ON uo.user_id = u.id
WHERE uo.organization_id = #{organizationId}
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.display_name LIKE CONCAT('%', #{keyword}, '%'))

mapper.select:
SELECT id, username, display_name, mobile, password_hash, user_type, status, created_at, updated_at
FROM sys_user
WHERE id = #{id}

SELECT id, username, display_name, mobile, password_hash, user_type, status, created_at, updated_at
FROM sys_user
WHERE username = #{username}

SELECT id, username, display_name, mobile, password_hash, user_type, status, created_at, updated_at
FROM sys_user WHERE username = #{username}
FOR UPDATE

mapper.update:
UPDATE sys_user
SET username = CASE WHEN username = #{expectedMobile} THEN #{newMobile} ELSE username END,
    mobile = #{newMobile},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND mobile = #{expectedMobile}
